fn ancestor(self: Cell, q: i64) Cell {
    const g = grid(self.s, q);
    return .init(self.s, q, @divFloor(self.x * g.w, self.w), @divFloor(self.y * g.h, self.h));
fn key(self: Cell) [3]i64 {
    return .{ self.p, self.x, self.y };
fn less(_: void, a: Cell, b: Cell) bool {
    return a.p < b.p or (a.p == b.p and (a.y > b.y or (a.y == b.y and a.x < b.x)));
} else if (std.mem.eql(u8, op, "DECODE") or std.mem.eql(u8, op, "NEIGHBORS") or std.mem.eql(u8, op, "PARENT") or std.mem.eql(u8, op, "CHILDREN")) {
    const pos = position(c.s, c.p).?;
        if (pos == 0) try out.writeAll("NONE") else try writeCode(gpa, out, c.ancestor(sequence[pos - 1]), "-");
    } else if (pos + 1 == sequence.len) try out.writeAll("NONE") else {
        const q = sequence[pos + 1];
        const g = grid(c.s, q);
        const rx = @divFloor(g.w, c.w);
        const ry = @divFloor(g.h, c.h);
        if (rx * ry > 100) {
            try out.writeAll("TOO MANY");
            return;
} else if (std.mem.eql(u8, op, "COMPACT")) {
    const s = try system(a[1]);
    var cells: std.AutoArrayHashMapUnmanaged([3]i64, Cell) = .empty;
    for (a[2..]) |code| {
        const c = try decode(s, code);
        try cells.put(gpa, c.key(), c);
    }
    var i: usize = 0;
    while (i < cells.count()) {
        const c = cells.values()[i];
        var contained = false;
        for (sequences[s]) |q| {
            if (q < c.p and cells.contains(c.ancestor(q).key())) {
                contained = true;
                break;
        if (contained) _ = cells.orderedRemove(c.key()) else i += 1;
    var changed = true;
    while (changed) {
        changed = false;
        for (cells.values()) |c| {
            const pos = position(s, c.p).?;
            if (pos == 0) continue;
            const parent = c.ancestor(sequences[s][pos - 1]);
            const rx = @divFloor(c.w, parent.w);
            const ry = @divFloor(c.h, parent.h);
            var children: std.ArrayList(Cell) = .empty;
            var complete = true;
            var j: i64 = 0;
            while (j < ry) : (j += 1) {
                var x: i64 = 0;
                while (x < rx) : (x += 1) {
                    const child = Cell.init(s, c.p, parent.x * rx + x, parent.y * ry + j);
                    if (!cells.contains(child.key())) complete = false;
                    try children.append(gpa, child);
            if (complete) {
                for (children.items) |child| _ = cells.orderedRemove(child.key());
                try cells.put(gpa, parent.key(), parent);
                changed = true;
                break;
    const ordered = try gpa.dupe(Cell, cells.values());
    std.mem.sort(Cell, ordered, {}, Cell.less);
    for (ordered, 0..) |c, j| {
        if (j > 0) try out.writeByte(' ');
        try writeCode(gpa, out, c, "-");
